local Baker = {}
local PRODUCTS = {
    bread = { name = "Kruh", flourCost = 2, time = 1, cost = 5, food = 10, happiness = 1, description = "Osnovni kruh." },
    cake = { name = "Torta", flourCost = 5, sugarCost = 3, time = 4, cost = 50, happiness = 8, prestige = 3, description = "Sladka torta." },
    pastry = { name = "Testenina", flourCost = 3, butterCost = 2, time = 2, cost = 20, happiness = 5, description = "Listnato pecivo." },
    pie = { name = "Pita", flourCost = 3, meatCost = 2, time = 3, cost = 30, food = 15, happiness = 4, description = "Mesna pita." },
    biscuit = { name = "Biskvit", flourCost = 2, sugarCost = 2, time = 2, cost = 15, happiness = 3, description = "Trdi biskvit." },
    wedding_cake = { name = "Svatbena torta", flourCost = 10, sugarCost = 8, time = 14, cost = 500, happiness = 25, prestige = 20, description = "Velika svatbena torta." },
}
local BUILDINGS = {
    bakery = { name = "Pekarna", cost = { gold = 200, wood = 100, stone = 50 }, upkeep = 8, qualityBonus = 5, description = "Pekarna s pečjo." },
    confectionery = { name = "Slaščičarna", cost = { gold = 800, wood = 200, stone = 200 }, upkeep = 20, qualityBonus = 15, description = "Za sladice in torte." },
    mill = { name = "Mlin", cost = { gold = 500, wood = 200, stone = 300 }, upkeep = 12, flourProduction = 10, description = "Za mletje moke." },
    royal_bakery = { name = "Kraljevska pekarna", cost = { gold = 3000, wood = 400, stone = 800 }, upkeep = 60, qualityBonus = 35, prestigeBonus = 15, description = "Najboljša pekarna." },
}
Baker.flourStock = 30; Baker.sugarStock = 10; Baker.butterStock = 10; Baker.meatStock = 10
Baker.productStock = {}; Baker.buildings = {}; Baker.baker = nil; Baker.activeBaking = {}; Baker.totalProducts = 0; Baker.dayTimer = 0
function Baker.init() Baker.flourStock=30; Baker.sugarStock=10; Baker.butterStock=10; Baker.meatStock=10; Baker.productStock={}; Baker.buildings={}; Baker.baker=nil; Baker.activeBaking={}; Baker.totalProducts=0; Baker.dayTimer=0; print("[Baker] Royal Baker & Confectioner System initialized (6 products, 4 buildings)") end
function Baker.hireBaker(n,s) s=s or math.random(35,80); local c=250+s*5; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; Baker.baker={name=n or ("Pek "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsBaked=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pek najet: %s (spretnost: %d)",Baker.baker.name,s),"success") end; return true end
function Baker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function Baker.build(id) local ok,e=Baker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(Baker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function Baker.getQualityBonus() local b=0; for _,bd in ipairs(Baker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function Baker.canBake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if Baker.flourStock<(d.flourCost or 0) then return false,"Premalo moke" end; if d.sugarCost and Baker.sugarStock<d.sugarCost then return false,"Premalo sladkorja" end; if d.butterCost and Baker.butterStock<d.butterCost then return false,"Premalo masla" end; if d.meatCost and Baker.meatStock<d.meatCost then return false,"Premalo mesa" end; if #Baker.buildings==0 then return false,"Potrebna pekarna" end; if not Baker.baker then return false,"Potreben pek" end; return true end
function Baker.bake(pt) local ok,e=Baker.canBake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; Baker.flourStock=Baker.flourStock-(d.flourCost or 0); if d.sugarCost then Baker.sugarStock=Baker.sugarStock-d.sugarCost end; if d.butterCost then Baker.butterStock=Baker.butterStock-d.butterCost end; if d.meatCost then Baker.meatStock=Baker.meatStock-d.meatCost end; local t=d.time; if Baker.baker then t=math.max(1,t-math.floor(Baker.baker.skill/15)) end; table.insert(Baker.activeBaking,{id="bake_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost,food=d.food or 0,happiness=d.happiness or 0,prestige=d.prestige or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pečenje: %s (%d dni)",d.name,t),"info") end; return true end
function Baker.completeBaking(b) local q=1.0+(Baker.getQualityBonus()/100); if Baker.baker then q=q+(Baker.baker.skill/200) end; q=math.min(2.0,q); Baker.productStock[b.productType]=(Baker.productStock[b.productType] or 0)+1; Baker.totalProducts=Baker.totalProducts+1; if _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+b.happiness*q) end; if b.food>0 and _G.state and _G.state.resources then _G.state.resources.food=(_G.state.resources.food or 0)+math.floor(b.food*q) end; if b.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+b.prestige) end; if Baker.baker then Baker.baker.itemsBaked=Baker.baker.itemsBaked+1; if math.random()<0.15 then Baker.baker.skill=math.min(100,Baker.baker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izpečeno: %s (kakovost: %.1f)",b.productName,q),"success") end end
function Baker.update(dt) if not _G.state then return end; Baker.dayTimer=Baker.dayTimer+dt; if Baker.dayTimer>=30 then Baker.dayTimer=0; for i=#Baker.activeBaking,1,-1 do local b=Baker.activeBaking[i]; b.daysRemaining=b.daysRemaining-1; if b.daysRemaining<=0 then Baker.completeBaking(b); table.remove(Baker.activeBaking,i) end end; local tu=0; for _,bd in ipairs(Baker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if Baker.baker then tu=tu+8 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function Baker.getStats() return {flourStock=Baker.flourStock,sugarStock=Baker.sugarStock,productStock=Baker.productStock,numBuildings=#Baker.buildings,hasBaker=Baker.baker~=nil,bakerName=Baker.baker and Baker.baker.name or "—",bakerSkill=Baker.baker and Baker.baker.skill or 0,activeBaking=#Baker.activeBaking,totalProducts=Baker.totalProducts} end
return Baker
